local({
  wave_num <- as.numeric(sub("^w", "", wave))
  first_wave <- stats::ave(wave_num, ID, FUN = min)
  cluster <- if_else(wave_num == first_wave, as.numeric(SCLID), NA_real_)
  as.character(carry_within(cluster, ID, wave_num))
})

local({
  items <- cbind(as.numeric(YINT2A09), as.numeric(YINT2A10), as.numeric(YINT2A11), as.numeric(YINT2A12))
  items[!items %in% 1:4] <- NA
  if_else(is.na(YALL1C04), rowSums(items), NA_real_)
})

local({
  cm <- as.numeric(YPHY2A00)
  kg <- as.numeric(YPHY2B00)
  ok <- cm > 0 & !cm %in% c(999, 9999) & kg > 0 & !kg %in% c(999, 9999)
  if_else(ok %in% TRUE, "Self-reported", NA_character_)
})
